+    @Test
+    public void testOptimisticReadPerformance() throws Exception {
+        // Add baseline messages
+        for (int i = 0; i < 1000; i++) {
+            tracker.addMessage(i, i, System.currentTimeMillis() + 60000);
+        }
+
