+            backoff,
+            || async { self.sync_once().await.map_err(backoff::Error::transient) },
+            |err, wait_time: Duration| {
+                tracing::warn!(
+                    ?err,
+                    "Failed to sync Bitcoin wallet. We will retry in {} seconds",
+                    wait_time.as_secs()
