+function formatAssignedTo(assignedTo: AssignedTo): string {
+  if (!assignedTo) {
+    return "Unassigned";
+  }
+
+  if (typeof assignedTo === "string") {
+    return assignedTo;
+  }
+
+  if (typeof assignedTo === "object" && assignedTo.name) {
+    return assignedTo.name;
+  }
+
+  return "Unknown";
+}

