+    const svgStr = createSvgStr(SquareCheck, customAttrs);
+    
+    // Check that all custom attributes are included
+    Object.entries(customAttrs).forEach(([key, value]) => {
+      expect(svgStr).toContain(`${key}="${value}"`);
+    });
+  });
 });

